import React from "react";
import "./App.css";
import PetCard from "./components/petCard";
import OurPetsSection from "./components/ourPetsSection";
function App() {
  return (
    <div className="container mt-4">
      <div className="row">
        <div className="col-md-3">
          <PetCard title="Card 1" description="This is card 1"/>
        </div>
        <div className="col-md-3">
          <PetCard title="Card 2" description="This is card 2" />
        </div>
        <div className="col-md-3">
          <PetCard title="Card 3" description="This is card 3" />
        </div>
        <div className="col-md-3">
          <PetCard title="Card 4" description="This is card 4"/>
        </div>
      </div>
    </div>
  );
}

export default App;
